func formatXlinkPropertyLabel(title, href string) string {
	t := strings.TrimSpace(title)
	h := strings.TrimSpace(href)
	if t != "" && h != "" && !strings.Contains(strings.ToLower(t), strings.ToLower(h)) {
		shortH := strings.TrimPrefix(h, "urn:uuid:")
		shortH = strings.TrimPrefix(shortH, "#")
		if len(shortH) > 20 {
			return t
		}
		return fmt.Sprintf("%s (%s)", t, shortH)
	}
	if t != "" {
		return t
	}
	if h != "" {
		return strings.TrimPrefix(strings.TrimPrefix(h, "urn:uuid:"), "#")
	}
	return "Unspecified"
}

func formatAuthoritySummary(authTS *aixmfeatures.AuthorityForAirspaceTimeSliceType) string {
	if authTS == nil {
		return ""
	}
	authType := "AUTH"
	if authTS.Type_XSD != nil && strings.TrimSpace(authTS.Type_XSD.EnclosedText) != "" {
		authType = strings.TrimSpace(authTS.Type_XSD.EnclosedText)
	}
	org := ""
	if authTS.ResponsibleOrganisation != nil {
		org = formatXlinkPropertyLabel(authTS.ResponsibleOrganisation.Title, authTS.ResponsibleOrganisation.Href)
	}
	notes := extractNotesSummary(authTS.Annotation)
	if notes != "" && org != "" {
		return fmt.Sprintf("[%s] %s — %s", authType, org, notes)
	}
	if org != "" {
		return fmt.Sprintf("[%s] %s", authType, org)
	}
	if notes != "" {
		return fmt.Sprintf("[%s] %s", authType, notes)
	}
	return fmt.Sprintf("[%s] %s", authType, authTS.Id)
}

func extractNotesSummary(notes []*aixmfeatures.NotePropertyType) string {
	var parts []string
	for _, np := range notes {
		if np == nil || np.Note == nil {
			continue
		}
		for _, tn := range np.Note.TranslatedNote {
			if tn != nil && tn.LinguisticNote != nil && tn.LinguisticNote.Note != nil {
				txt := strings.TrimSpace(tn.LinguisticNote.Note.EnclosedText)
				if txt != "" {
					parts = append(parts, txt)
				}
			}
		}
	}
	return strings.Join(parts, "; ")
}

func formatTimesheetSummary(ts *aixmfeatures.TimesheetType) string {
	if ts == nil {
		return ""
	}
	var parts []string
	if ts.Day != nil && strings.TrimSpace(ts.Day.EnclosedText) != "" {
		dayStr := strings.TrimSpace(ts.Day.EnclosedText)
		if ts.DayTil != nil && strings.TrimSpace(ts.DayTil.EnclosedText) != "" {
			dayStr += "->" + strings.TrimSpace(ts.DayTil.EnclosedText)
		}
		parts = append(parts, dayStr)
	}
	startT := ""
	if ts.StartTime != nil && strings.TrimSpace(ts.StartTime.EnclosedText) != "" {
		startT = strings.TrimSpace(ts.StartTime.EnclosedText)
	} else if ts.StartEvent != nil && strings.TrimSpace(ts.StartEvent.EnclosedText) != "" {
		startT = strings.TrimSpace(ts.StartEvent.EnclosedText)
	}
	endT := ""
	if ts.EndTime != nil && strings.TrimSpace(ts.EndTime.EnclosedText) != "" {
		endT = strings.TrimSpace(ts.EndTime.EnclosedText)
	} else if ts.EndEvent != nil && strings.TrimSpace(ts.EndEvent.EnclosedText) != "" {
		endT = strings.TrimSpace(ts.EndEvent.EnclosedText)
	}
	if startT != "" || endT != "" {
		if startT == "" {
			startT = "00:00"
		}
		if endT == "" {
			endT = "24:00"
		}
		parts = append(parts, startT+"-"+endT)
	}
	if ts.TimeReference != nil && strings.TrimSpace(ts.TimeReference.EnclosedText) != "" {
		parts = append(parts, strings.TrimSpace(ts.TimeReference.EnclosedText))
	}
	if ts.StartDate != nil && strings.TrimSpace(ts.StartDate.EnclosedText) != "" {
		dateRange := strings.TrimSpace(ts.StartDate.EnclosedText)
		if ts.EndDate != nil && strings.TrimSpace(ts.EndDate.EnclosedText) != "" {
			dateRange += " to " + strings.TrimSpace(ts.EndDate.EnclosedText)
		}
		parts = append(parts, "("+dateRange+")")
	}
	if ts.Excluded != nil && strings.EqualFold(strings.TrimSpace(ts.Excluded.EnclosedText), "YES") {
		parts = append(parts, "[EXCLUDED]")
	}
	if len(parts) == 0 {
		return "Timesheet " + ts.Id
	}
	return strings.Join(parts, " ")
}

func (stager *Stager) buildNoteNodes(notes []*aixmfeatures.NotePropertyType) []*tree.Node {
	var res []*tree.Node
	for _, np := range notes {
		if np == nil || np.Note == nil {
			continue
		}
		noteObj := np.Note
		purpose := ""
		if noteObj.Purpose != nil && strings.TrimSpace(noteObj.Purpose.EnclosedText) != "" {
			purpose = strings.TrimSpace(noteObj.Purpose.EnclosedText)
		}
		propName := ""
		if noteObj.PropertyName != nil && strings.TrimSpace(noteObj.PropertyName.EnclosedText) != "" {
			propName = strings.TrimSpace(noteObj.PropertyName.EnclosedText)
		}
		var texts []string
		for _, tn := range noteObj.TranslatedNote {
			if tn != nil && tn.LinguisticNote != nil && tn.LinguisticNote.Note != nil {
				t := strings.TrimSpace(tn.LinguisticNote.Note.EnclosedText)
				if t != "" {
					texts = append(texts, t)
				}
			}
		}
		txt := strings.Join(texts, " | ")
		if txt == "" {
			txt = noteObj.Id
		}
		prefix := "Note"
		if purpose != "" && propName != "" {
			prefix = fmt.Sprintf("Note [%s / %s]", purpose, propName)
		} else if purpose != "" {
			prefix = fmt.Sprintf("Note [%s]", purpose)
		} else if propName != "" {
			prefix = fmt.Sprintf("Note [%s]", propName)
		}
		res = append(res, &tree.Node{
			Name:            fmt.Sprintf("%s: %s", prefix, txt),
			IsNodeClickable: true,
			OnClick: func(frontNode *tree.Node) {
				stager.mu.Lock()
				defer stager.mu.Unlock()
				if stager.probeForm != nil {
					stager.probeForm.FillUpFormFromGongstruct(noteObj, "NoteType")
				}
			},
		})
	}
	return res
}

func (stager *Stager) buildAirspaceDetailChildren(
	as *aixmfeatures.AirspaceType,
	ts *aixmfeatures.AirspaceTimeSliceType,
	authorities []*aixmfeatures.AuthorityForAirspaceTimeSliceType,
	airspaceByKey map[string]*aixmfeatures.AirspaceType,
) []*tree.Node {
	var children []*tree.Node
	if ts == nil {
		return children
	}

	// 1. Responsible Authorities (Direct AuthorityForAirspace + Inherited FIR/State Authority + ADR AMC/OwnerRSA + Activation User + ICAO State/ANSP)
	var authNodes []*tree.Node
	var primaryHeadline string

	desig := ""
	if ts.Designator != nil {
		desig = strings.TrimSpace(ts.Designator.EnclosedText)
	}
	asName := ""
	for _, n := range ts.NameXSD {
		if n != nil && strings.TrimSpace(n.EnclosedText) != "" {
			asName = strings.TrimSpace(n.EnclosedText)
			break
		}
	}
	shortKey := desig
	if shortKey == "" {
		shortKey = asName
	}
	pfx2 := airspaceTwoLetterPrefix(shortKey)
	countryName, icaoAuth := icaoPrefixAuthorityInfo(pfx2)

	var asIdentifier string
	if as != nil && as.Identifier != nil {
		asIdentifier = as.Identifier.EnclosedText
	}
	var asID string
	if as != nil {
		asID = as.Id
	}
	adrExt := GetADRAirspaceExtension(ts.Id, asID, asIdentifier, "desig:"+desig)

	// 1a. Staged AuthorityForAirspace (Direct or Inherited via FIR/NAS)
	for _, authTS := range authorities {
		authTS := authTS
		summary := formatAuthoritySummary(authTS)
		assignedAS := airspaceByKey["auth_assigned:"+normalizeAirspaceKey(authTS.Id)]
		isInherited := assignedAS != nil && assignedAS != as
		nodeTitle := "Authority: " + summary
		if isInherited {
			assignedSummary := formatAirspaceSummary(assignedAS)
			nodeTitle = fmt.Sprintf("Authority (via %s): %s", assignedSummary, summary)
		}
		if primaryHeadline == "" {
			if isInherited {
				primaryHeadline = fmt.Sprintf("%s (via %s)", summary, formatAirspaceSummary(assignedAS))
			} else {
				primaryHeadline = summary
			}
		}

		authNode := &tree.Node{
			Name:            nodeTitle,
			IsExpanded:      true,
			IsNodeClickable: true,
			OnClick: func(frontNode *tree.Node) {
				stager.mu.Lock()
				defer stager.mu.Unlock()
				if stager.probeForm != nil {
					stager.probeForm.FillUpFormFromGongstruct(authTS, "AuthorityForAirspaceTimeSliceType")
				}
			},
		}
		if authTS.ResponsibleOrganisation != nil {
			orgProp := authTS.ResponsibleOrganisation
			orgLabel := formatXlinkPropertyLabel(orgProp.Title, orgProp.Href)
			authNode.Children = append(authNode.Children, &tree.Node{
				Name:            "Responsible Organisation: " + orgLabel,
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(orgProp, "OrganisationAuthorityPropertyType")
					}
				},
			})
		}
		if isInherited && assignedAS != nil {
			assignedAS := assignedAS
			authNode.Children = append(authNode.Children, &tree.Node{
				Name:            "-> Assigned FIR / State Airspace: " + formatAirspaceSummary(assignedAS),
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					stager.selectAndFocusAirspaceLocked(assignedAS)
				},
			})
		}
		authNode.Children = append(authNode.Children, stager.buildNoteNodes(authTS.Annotation)...)
		authNodes = append(authNodes, authNode)
	}

	// 1b. Activation User authorities and SpecialDateAuthorities
	seenOrgLabels := make(map[string]bool)
	for _, actProp := range ts.Activation {
		if actProp == nil || actProp.AirspaceActivation == nil {
			continue
		}
		act := actProp.AirspaceActivation
		for _, u := range act.User {
			if u == nil || (u.Title == "" && u.Href == "") {
				continue
			}
			u := u
			lbl := formatXlinkPropertyLabel(u.Title, u.Href)
			key := "USER:" + lbl
			if seenOrgLabels[key] {
				continue
			}
			seenOrgLabels[key] = true
			if primaryHeadline == "" {
				primaryHeadline = lbl
			}
			authNodes = append(authNodes, &tree.Node{
				Name:            "User / Operating Authority: " + lbl,
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(u, "OrganisationAuthorityPropertyType")
					}
				},
			})
		}
		for _, sda := range act.SpecialDateAuthority {
			if sda == nil || (sda.Title == "" && sda.Href == "") {
				continue
			}
			sda := sda
			lbl := formatXlinkPropertyLabel(sda.Title, sda.Href)
			key := "SDA:" + lbl
			if seenOrgLabels[key] {
				continue
			}
			seenOrgLabels[key] = true
			if primaryHeadline == "" {
				primaryHeadline = lbl
			}
			authNodes = append(authNodes, &tree.Node{
				Name:            "Special Date Authority: " + lbl,
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(sda, "OrganisationAuthorityPropertyType")
					}
				},
			})
		}
	}
	for _, clsProp := range ts.Class {
		if clsProp == nil || clsProp.AirspaceLayerClass == nil {
			continue
		}
		for _, sda := range clsProp.AirspaceLayerClass.SpecialDateAuthority {
			if sda == nil || (sda.Title == "" && sda.Href == "") {
				continue
			}
			sda := sda
			lbl := formatXlinkPropertyLabel(sda.Title, sda.Href)
			key := "SDA:" + lbl
			if seenOrgLabels[key] {
				continue
			}
			seenOrgLabels[key] = true
			if primaryHeadline == "" {
				primaryHeadline = lbl
			}
			authNodes = append(authNodes, &tree.Node{
				Name:            "Special Date Authority: " + lbl,
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(sda, "OrganisationAuthorityPropertyType")
					}
				},
			})
		}
	}

	// 1c. Eurocontrol ADR Extension Authorities (Responsible AMC, Requestor, Owner RSA for FBZ, Host Airspace, FUA/AMC management)
	var adrRoleTags []string
	if adrExt != nil {
		if adrExt.ResponsibleAMCTitle != "" || adrExt.ResponsibleAMCHref != "" {
			amcLbl := formatXlinkPropertyLabel(adrExt.ResponsibleAMCTitle, adrExt.ResponsibleAMCHref)
			if primaryHeadline == "" {
				primaryHeadline = "AMC: " + amcLbl
			}
			authNodes = append(authNodes, &tree.Node{
				Name: "Responsible AMC: " + amcLbl,
			})
		}
		if adrExt.RequestorTitle != "" || adrExt.RequestorHref != "" {
			reqLbl := formatXlinkPropertyLabel(adrExt.RequestorTitle, adrExt.RequestorHref)
			authNodes = append(authNodes, &tree.Node{
				Name: "Requestor Authority: " + reqLbl,
			})
		}
		var mgmtParts []string
		if strings.EqualFold(adrExt.IsAMC, "YES") {
			mgmtParts = append(mgmtParts, "AMC Managed (isAMC: YES)")
			adrRoleTags = append(adrRoleTags, "AMC Managed")
		}
		if strings.EqualFold(adrExt.FlexibleUse, "YES") {
			var lvls []string
			if strings.EqualFold(adrExt.Level1, "YES") {
				lvls = append(lvls, "1")
			}
			if strings.EqualFold(adrExt.Level2, "YES") {
				lvls = append(lvls, "2")
			}
			if strings.EqualFold(adrExt.Level3, "YES") {
				lvls = append(lvls, "3")
			}
			if len(lvls) > 0 {
				fuaStr := "FUA Level " + strings.Join(lvls, "/")
				mgmtParts = append(mgmtParts, "Flexible Use ("+fuaStr+")")
				adrRoleTags = append(adrRoleTags, fuaStr)
			} else {
				mgmtParts = append(mgmtParts, "Flexible Use (FUA)")
				adrRoleTags = append(adrRoleTags, "FUA")
			}
		}
		if strings.EqualFold(adrExt.IsFBZ, "YES") {
			mgmtParts = append(mgmtParts, "Flight Buffer Zone (FBZ)")
		}
		if adrExt.Usage != "" {
			mgmtParts = append(mgmtParts, "Usage: "+adrExt.Usage)
		}
		if len(mgmtParts) > 0 {
			authNodes = append(authNodes, &tree.Node{
				Name: "ADR Management: " + strings.Join(mgmtParts, " | "),
			})
		}
	}

	// Resolve Owner RSA (for Flight Buffer Zones like LFCBA1THZ or LKTRA19Z) via ADR ownerRSA href OR designator suffix "Z"
	var ownerRSA *aixmfeatures.AirspaceType
	var ownerRSALabel string
	parentDesig := ""
	if strings.HasSuffix(strings.ToUpper(desig), "Z") && (strings.Contains(strings.ToUpper(asName), "FBZ") || (adrExt != nil && strings.EqualFold(adrExt.IsFBZ, "YES"))) {
		parentDesig = strings.TrimSuffix(strings.ToUpper(desig), "Z")
	}
	if adrExt != nil && (adrExt.OwnerRSAHref != "" || adrExt.OwnerRSATitle != "") {
		if adrExt.OwnerRSAHref != "" {
			ownerRSA = airspaceByKey[normalizeAirspaceKey(adrExt.OwnerRSAHref)]
		}
		if ownerRSA == nil && parentDesig != "" {
			ownerRSA = airspaceByKey["desig:"+strings.ToLower(parentDesig)]
		}
		if ownerRSA != nil {
			ownerRSALabel = formatAirspaceSummary(ownerRSA)
		} else if parentDesig != "" {
			parentName := strings.TrimSpace(strings.TrimSuffix(strings.TrimSpace(asName), "FBZ"))
			if parentName != "" && parentName != parentDesig {
				ownerRSALabel = fmt.Sprintf("%s - %s (%s)", parentDesig, parentName, formatXlinkPropertyLabel(adrExt.OwnerRSATitle, adrExt.OwnerRSAHref))
			} else {
				ownerRSALabel = fmt.Sprintf("%s (%s)", parentDesig, formatXlinkPropertyLabel(adrExt.OwnerRSATitle, adrExt.OwnerRSAHref))
			}
		} else {
			ownerRSALabel = formatXlinkPropertyLabel(adrExt.OwnerRSATitle, adrExt.OwnerRSAHref)
		}
	} else if parentDesig != "" {
		if parentAS := airspaceByKey["desig:"+strings.ToLower(parentDesig)]; parentAS != nil && parentAS != as {
			ownerRSA = parentAS
			ownerRSALabel = formatAirspaceSummary(parentAS)
		} else {
			parentName := strings.TrimSpace(strings.TrimSuffix(strings.TrimSpace(asName), "FBZ"))
			if parentName != "" && parentName != parentDesig {
				ownerRSALabel = fmt.Sprintf("%s - %s", parentDesig, parentName)
			} else {
				ownerRSALabel = parentDesig
			}
		}
	}
	if ownerRSALabel != "" {
		ownerRSA := ownerRSA
		adrRoleTags = append(adrRoleTags, "FBZ")
		authNodes = append(authNodes, &tree.Node{
			Name:            "-> Owner RSA (Parent Zone): " + ownerRSALabel,
			IsNodeClickable: ownerRSA != nil,
			OnClick: func(frontNode *tree.Node) {
				if ownerRSA == nil {
					return
				}
				stager.mu.Lock()
				defer stager.mu.Unlock()
				stager.selectAndFocusAirspaceLocked(ownerRSA)
			},
		})
	}

	// Resolve Host Airspaces from ADR extension if present
	if adrExt != nil {
		for _, hostHref := range adrExt.HostAirspaceHrefs {
			hostAS := airspaceByKey[normalizeAirspaceKey(hostHref)]
			hostLbl := formatXlinkPropertyLabel("", hostHref)
			if hostAS != nil {
				hostLbl = formatAirspaceSummary(hostAS)
			}
			authNodes = append(authNodes, &tree.Node{
				Name:            "-> Host Airspace: " + hostLbl,
				IsNodeClickable: hostAS != nil,
				OnClick: func(frontNode *tree.Node) {
					if hostAS == nil {
						return
					}
					stager.mu.Lock()
					defer stager.mu.Unlock()
					stager.selectAndFocusAirspaceLocked(hostAS)
				},
			})
		}
	}

	// 1d. ICAO State / ANSP / AMC Authority & Enclosing National/FIR Airspaces in the Stage
	if countryName != "" && icaoAuth != "" {
		stateSummary := fmt.Sprintf("%s — %s", countryName, icaoAuth)
		if primaryHeadline == "" {
			if len(adrRoleTags) > 0 {
				primaryHeadline = fmt.Sprintf("%s [%s]", stateSummary, strings.Join(adrRoleTags, ", "))
			} else {
				primaryHeadline = stateSummary
			}
		}
		authNodes = append(authNodes, &tree.Node{
			Name:            fmt.Sprintf("State / ANSP Authority [%s]: %s", pfx2, stateSummary),
			IsNodeClickable: true,
			OnClick: func(frontNode *tree.Node) {
				stager.mu.Lock()
				defer stager.mu.Unlock()
				if stager.probeForm != nil {
					stager.probeForm.FillUpFormFromGongstruct(ts, "AirspaceTimeSliceType")
				}
			},
		})
	}

	if pfx2 != "" && pfx2 != "#" {
		if nasAS := airspaceByKey["nas:"+strings.ToLower(pfx2)]; nasAS != nil && nasAS != as {
			nasAS := nasAS
			nasSummary := formatAirspaceSummary(nasAS)
			if primaryHeadline == "" {
				primaryHeadline = nasSummary
			}
			authNodes = append(authNodes, &tree.Node{
				Name:            "-> National Airspace [NAS]: " + nasSummary,
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					stager.selectAndFocusAirspaceLocked(nasAS)
				},
			})
		}
		if firAS := airspaceByKey["fir:"+strings.ToLower(pfx2)]; firAS != nil && firAS != as {
			firAS := firAS
			firSummary := formatAirspaceSummary(firAS)
			if primaryHeadline == "" {
				primaryHeadline = firSummary
			}
			authNodes = append(authNodes, &tree.Node{
				Name:            "-> Enclosing FIR Airspace: " + firSummary,
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					stager.selectAndFocusAirspaceLocked(firAS)
				},
			})
		}
	}

	if len(authNodes) == 1 {
		if !strings.HasPrefix(authNodes[0].Name, "Authority") {
			authNodes[0].Name = "Authority: " + authNodes[0].Name
		}
		children = append(children, authNodes[0])
	} else if len(authNodes) > 1 {
		if primaryHeadline == "" {
			primaryHeadline = strings.TrimPrefix(authNodes[0].Name, "Authority: ")
		}
		authGroupNode := &tree.Node{
			Name:       "Authority: " + primaryHeadline,
			IsExpanded: true,
			Children:   authNodes,
		}
		children = append(children, authGroupNode)
	}

	// 2. General Operational Properties (ControlType, LocalType, UpperLowerSeparation, ProtectedRoute)
	var propParts []string
	if ts.ControlType != nil && strings.TrimSpace(ts.ControlType.EnclosedText) != "" {
		propParts = append(propParts, "Control: "+strings.TrimSpace(ts.ControlType.EnclosedText))
	}
	if ts.LocalType != nil && strings.TrimSpace(ts.LocalType.EnclosedText) != "" {
		propParts = append(propParts, "LocalType: "+strings.TrimSpace(ts.LocalType.EnclosedText))
	}
	if ts.DesignatorICAO != nil && strings.TrimSpace(ts.DesignatorICAO.EnclosedText) != "" {
		propParts = append(propParts, "ICAO: "+strings.TrimSpace(ts.DesignatorICAO.EnclosedText))
	}
	if ts.UpperLowerSeparation != nil && ts.UpperLowerSeparation.EnclosedText != 0 {
		uom := ts.UpperLowerSeparation.Uom
		if uom == "" {
			uom = "FL"
		}
		propParts = append(propParts, fmt.Sprintf("Upper/Lower Sep: %s %d", uom, ts.UpperLowerSeparation.EnclosedText))
	}
	if len(propParts) > 0 {
		children = append(children, &tree.Node{
			Name:            strings.Join(propParts, " | "),
			IsNodeClickable: true,
			OnClick: func(frontNode *tree.Node) {
				stager.mu.Lock()
				defer stager.mu.Unlock()
				if stager.probeForm != nil {
					stager.probeForm.FillUpFormFromGongstruct(ts, "AirspaceTimeSliceType")
				}
			},
		})
	}

	if ts.ProtectedRoute != nil && (ts.ProtectedRoute.Title != "" || ts.ProtectedRoute.Href != "") {
		pr := ts.ProtectedRoute
		children = append(children, &tree.Node{
			Name:            "Protected Route: " + formatXlinkPropertyLabel(pr.Title, pr.Href),
			IsNodeClickable: true,
			OnClick: func(frontNode *tree.Node) {
				stager.mu.Lock()
				defer stager.mu.Unlock()
				if stager.probeForm != nil {
					stager.probeForm.FillUpFormFromGongstruct(pr, "RoutePropertyType")
				}
			},
		})
	}

	// 3. Airspace Classifications & Vertical Layers (ts.Class)
	for _, clsProp := range ts.Class {
		if clsProp == nil || clsProp.AirspaceLayerClass == nil {
			continue
		}
		cls := clsProp.AirspaceLayerClass
		clsCode := "?"
		if cls.Classification != nil && strings.TrimSpace(cls.Classification.EnclosedText) != "" {
			clsCode = strings.TrimSpace(cls.Classification.EnclosedText)
		}
		var levelSummaries []string
		var layerNodes []*tree.Node
		for _, lp := range cls.AssociatedLevels {
			if lp == nil || lp.AirspaceLayer == nil {
				continue
			}
			layer := lp.AirspaceLayer
			lvlStr := formatVerticalLimits(layer.LowerLimit, layer.UpperLimit)
			if layer.DiscreteLevelSeries != nil && layer.DiscreteLevelSeries.Title != "" {
				if lvlStr != "" {
					lvlStr += " [" + strings.TrimSpace(layer.DiscreteLevelSeries.Title) + "]"
				} else {
					lvlStr = strings.TrimSpace(layer.DiscreteLevelSeries.Title)
				}
			}
			if lvlStr != "" {
				levelSummaries = append(levelSummaries, lvlStr)
			}
			layerNodes = append(layerNodes, &tree.Node{
				Name:            "Layer Levels: " + lvlStr,
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(layer, "AirspaceLayerType")
					}
				},
			})
		}
		clsTitle := fmt.Sprintf("Class %s", clsCode)
		if len(levelSummaries) > 0 {
			clsTitle = fmt.Sprintf("Class %s (%s)", clsCode, strings.Join(levelSummaries, ", "))
		}
		clsNode := &tree.Node{
			Name:            clsTitle,
			IsNodeClickable: true,
			Children:        layerNodes,
			OnClick: func(frontNode *tree.Node) {
				stager.mu.Lock()
				defer stager.mu.Unlock()
				if stager.probeForm != nil {
					stager.probeForm.FillUpFormFromGongstruct(cls, "AirspaceLayerClassType")
				}
			},
		}
		for _, tip := range cls.TimeInterval {
			if tip == nil || tip.Timesheet == nil {
				continue
			}
			tsh := tip.Timesheet
			clsNode.Children = append(clsNode.Children, &tree.Node{
				Name:            "Schedule: " + formatTimesheetSummary(tsh),
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(tsh, "TimesheetType")
					}
				},
			})
		}
		clsNode.Children = append(clsNode.Children, stager.buildNoteNodes(cls.Annotation)...)
		children = append(children, clsNode)
	}

	// 4. Activations & Schedules (ts.Activation)
	for _, actProp := range ts.Activation {
		if actProp == nil || actProp.AirspaceActivation == nil {
			continue
		}
		act := actProp.AirspaceActivation
		status := "ACTIVE"
		if act.Status != nil && strings.TrimSpace(act.Status.EnclosedText) != "" {
			status = strings.TrimSpace(act.Status.EnclosedText)
		}
		activity := ""
		if act.Activity != nil && strings.TrimSpace(act.Activity.EnclosedText) != "" {
			activity = strings.TrimSpace(act.Activity.EnclosedText)
		}
		actLabel := fmt.Sprintf("Activation [%s]", status)
		if activity != "" {
			actLabel += " — Activity: " + activity
		}
		actNode := &tree.Node{
			Name:            actLabel,
			IsNodeClickable: true,
			OnClick: func(frontNode *tree.Node) {
				stager.mu.Lock()
				defer stager.mu.Unlock()
				if stager.probeForm != nil {
					stager.probeForm.FillUpFormFromGongstruct(act, "AirspaceActivationType")
				}
			},
		}
		for _, tip := range act.TimeInterval {
			if tip == nil || tip.Timesheet == nil {
				continue
			}
			tsh := tip.Timesheet
			actNode.Children = append(actNode.Children, &tree.Node{
				Name:            "Schedule: " + formatTimesheetSummary(tsh),
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(tsh, "TimesheetType")
					}
				},
			})
		}
		for _, lp := range act.Levels {
			if lp == nil || lp.AirspaceLayer == nil {
				continue
			}
			layer := lp.AirspaceLayer
			lvlStr := formatVerticalLimits(layer.LowerLimit, layer.UpperLimit)
			if layer.DiscreteLevelSeries != nil && layer.DiscreteLevelSeries.Title != "" {
				if lvlStr != "" {
					lvlStr += " [" + strings.TrimSpace(layer.DiscreteLevelSeries.Title) + "]"
				} else {
					lvlStr = strings.TrimSpace(layer.DiscreteLevelSeries.Title)
				}
			}
			actNode.Children = append(actNode.Children, &tree.Node{
				Name:            "Activation Levels: " + lvlStr,
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(layer, "AirspaceLayerType")
					}
				},
			})
		}
		for _, u := range act.User {
			if u == nil || (u.Title == "" && u.Href == "") {
				continue
			}
			u := u
			actNode.Children = append(actNode.Children, &tree.Node{
				Name:            "User Authority: " + formatXlinkPropertyLabel(u.Title, u.Href),
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(u, "OrganisationAuthorityPropertyType")
					}
				},
			})
		}
		for _, acp := range act.Aircraft {
			if acp == nil || acp.AircraftCharacteristic == nil {
				continue
			}
			ac := acp.AircraftCharacteristic
			var acParts []string
			if ac.Type_XSD != nil && strings.TrimSpace(ac.Type_XSD.EnclosedText) != "" {
				acParts = append(acParts, "Type: "+strings.TrimSpace(ac.Type_XSD.EnclosedText))
			}
			if ac.Engine != nil && strings.TrimSpace(ac.Engine.EnclosedText) != "" {
				acParts = append(acParts, "Engine: "+strings.TrimSpace(ac.Engine.EnclosedText))
			}
			if ac.NavigationSpecification != nil && strings.TrimSpace(ac.NavigationSpecification.EnclosedText) != "" {
				acParts = append(acParts, "NavSpec: "+strings.TrimSpace(ac.NavigationSpecification.EnclosedText))
			}
			if ac.VerticalSeparationCapability != nil && strings.TrimSpace(ac.VerticalSeparationCapability.EnclosedText) != "" {
				acParts = append(acParts, "RVSM: "+strings.TrimSpace(ac.VerticalSeparationCapability.EnclosedText))
			}
			acDesc := strings.Join(acParts, ", ")
			if acDesc == "" {
				acDesc = ac.Id
			}
			actNode.Children = append(actNode.Children, &tree.Node{
				Name:            "Aircraft: " + acDesc,
				IsNodeClickable: true,
				OnClick: func(frontNode *tree.Node) {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.probeForm != nil {
						stager.probeForm.FillUpFormFromGongstruct(ac, "AircraftCharacteristicType")
					}
				},
			})
		}
		actNode.Children = append(actNode.Children, stager.buildNoteNodes(act.Annotation)...)
		children = append(children, actNode)
	}

	// 5. Geometry Components, Volumes & Contributor Airspaces (ts.GeometryComponent)
	for gIdx, gcp := range ts.GeometryComponent {
		if gcp == nil || gcp.AirspaceGeometryComponent == nil {
			continue
		}
		gc := gcp.AirspaceGeometryComponent
		op := "BASE"
		if gc.Operation != nil && strings.TrimSpace(gc.Operation.EnclosedText) != "" {
			op = strings.TrimSpace(gc.Operation.EnclosedText)
		}
		seq := fmt.Sprintf("%d", gIdx+1)
		if gc.OperationSequence != nil && gc.OperationSequence.EnclosedText != 0 {
			seq = fmt.Sprintf("%d", gc.OperationSequence.EnclosedText)
		}

		var vol *aixmfeatures.AirspaceVolumeType
		if gc.TheAirspaceVolume != nil {
			vol = gc.TheAirspaceVolume.AirspaceVolume
		}
		limits := ""
		if vol != nil {
			limits = formatVerticalLimits(vol.LowerLimit, vol.UpperLimit)
		}
		geomLabel := fmt.Sprintf("Geometry [%s #%s]", op, seq)
		if limits != "" {
			geomLabel += " (" + limits + ")"
		}
		if vol != nil && vol.Width != nil && strings.TrimSpace(vol.Width.EnclosedText) != "" {
			geomLabel += fmt.Sprintf(" Width: %s %s", strings.TrimSpace(vol.Width.EnclosedText), vol.Width.Uom)
		}

		geomNode := &tree.Node{
			Name:            geomLabel,
			IsNodeClickable: true,
			OnClick: func(frontNode *tree.Node) {
				stager.mu.Lock()
				defer stager.mu.Unlock()
				if stager.probeForm != nil {
					if vol != nil {
						stager.probeForm.FillUpFormFromGongstruct(vol, "AirspaceVolumeType")
					} else {
						stager.probeForm.FillUpFormFromGongstruct(gc, "AirspaceGeometryComponentType")
					}
				}
			},
		}

		if vol != nil {
			// Check Contributor Airspace Dependency (allows clicking to jump to the referenced airspace!)
			if vol.ContributorAirspace != nil && vol.ContributorAirspace.AirspaceVolumeDependency != nil {
				dep := vol.ContributorAirspace.AirspaceVolumeDependency
				depType := "DEPENDENCY"
				if dep.Dependency != nil && strings.TrimSpace(dep.Dependency.EnclosedText) != "" {
					depType = strings.TrimSpace(dep.Dependency.EnclosedText)
				}
				refLabel := dep.Id
				var contribAS *aixmfeatures.AirspaceType
				if dep.TheAirspace != nil {
					if dep.TheAirspace.Href != "" {
						contribAS = airspaceByKey[normalizeAirspaceKey(dep.TheAirspace.Href)]
					}
					if contribAS != nil && strings.TrimSpace(dep.TheAirspace.Title) == "" {
						refLabel = formatAirspaceSummary(contribAS)
					} else {
						refLabel = formatXlinkPropertyLabel(dep.TheAirspace.Title, dep.TheAirspace.Href)
					}
				}
				contribNode := &tree.Node{
					Name:            fmt.Sprintf("-> Contributor Airspace [%s]: %s", depType, refLabel),
					IsNodeClickable: true,
					OnClick: func(frontNode *tree.Node) {
						stager.mu.Lock()
						defer stager.mu.Unlock()
						if contribAS != nil {
							stager.selectAndFocusAirspaceLocked(contribAS)
						} else if stager.probeForm != nil {
							stager.probeForm.FillUpFormFromGongstruct(dep, "AirspaceVolumeDependencyType")
						}
					},
				}
				geomNode.Children = append(geomNode.Children, contribNode)
			}

			// Horizontal Projection (Surface / ElevatedSurface)
			if vol.HorizontalProjection != nil {
				hp := vol.HorizontalProjection
				if hp.Surface != nil {
					surf := hp.Surface
					patchCount := 0
					if surf.Patches != nil {
						patchCount = len(surf.Patches.PolygonPatch)
					}
					geomNode.Children = append(geomNode.Children, &tree.Node{
						Name:            fmt.Sprintf("Horizontal Surface: %s (%d patch(es))", surf.Id, patchCount),
						IsNodeClickable: true,
						OnClick: func(frontNode *tree.Node) {
							stager.mu.Lock()
							defer stager.mu.Unlock()
							if stager.probeForm != nil {
								stager.probeForm.FillUpFormFromGongstruct(surf, "SurfaceType")
							}
						},
					})
				} else if hp.ElevatedSurface != nil {
					esurf := hp.ElevatedSurface
					geomNode.Children = append(geomNode.Children, &tree.Node{
						Name:            fmt.Sprintf("Elevated Surface: %s", esurf.Id),
						IsNodeClickable: true,
						OnClick: func(frontNode *tree.Node) {
							stager.mu.Lock()
							defer stager.mu.Unlock()
							if stager.probeForm != nil {
								stager.probeForm.FillUpFormFromGongstruct(esurf, "ElevatedSurfaceType")
							}
						},
					})
				}
			}

			// Centreline (Curve / ElevatedCurve)
			if vol.Centreline != nil {
				cl := vol.Centreline
				if cl.Curve != nil {
					crv := cl.Curve
					geomNode.Children = append(geomNode.Children, &tree.Node{
						Name:            fmt.Sprintf("Centreline Curve: %s", crv.Id),
						IsNodeClickable: true,
						OnClick: func(frontNode *tree.Node) {
							stager.mu.Lock()
							defer stager.mu.Unlock()
							if stager.probeForm != nil {
								stager.probeForm.FillUpFormFromGongstruct(crv, "CurveType")
							}
						},
					})
				}
			}

			geomNode.Children = append(geomNode.Children, stager.buildNoteNodes(vol.Annotation)...)
		}
		geomNode.Children = append(geomNode.Children, stager.buildNoteNodes(gc.Annotation)...)
		children = append(children, geomNode)
	}

	// 6. Annotations / Notes on the AirspaceTimeSlice itself
	children = append(children, stager.buildNoteNodes(ts.Annotation)...)

	return children
}

func (stager *Stager) selectAndFocusAirspaceLocked(as *aixmfeatures.AirspaceType) {
	if as == nil {
		return
	}
	if stager.hiddenAirspaces != nil {
		delete(stager.hiddenAirspaces, as)
	}
	if stager.expandedAirspaces == nil {
		stager.expandedAirspaces = make(map[*aixmfeatures.AirspaceType]bool)
	}
	stager.expandedAirspaces[as] = true

	var targetTS *aixmfeatures.AirspaceTimeSliceType
	asType := "OTHER"
	shortName := as.Name
	for _, tsp := range as.TimeSlice {
		if tsp != nil && tsp.AirspaceTimeSlice != nil {
			targetTS = tsp.AirspaceTimeSlice
			if targetTS.Type_XSD != nil && strings.TrimSpace(targetTS.Type_XSD.EnclosedText) != "" {
				asType = strings.ToUpper(strings.TrimSpace(targetTS.Type_XSD.EnclosedText))
			}
			if targetTS.Designator != nil && strings.TrimSpace(targetTS.Designator.EnclosedText) != "" {
				shortName = strings.TrimSpace(targetTS.Designator.EnclosedText)
			} else {
				for _, n := range targetTS.NameXSD {
					if n != nil && strings.TrimSpace(n.EnclosedText) != "" {
						shortName = strings.TrimSpace(n.EnclosedText)
						break
					}
				}
			}
			break
		}
	}
	if stager.expandedCategories == nil {
		stager.expandedCategories = make(map[string]bool)
	}
	letter := airspaceFirstLetter(shortName)
	pfx2 := airspaceTwoLetterPrefix(shortName)
	stager.expandedCategories["AS_CAT_"+asType] = true
	stager.expandedCategories[fmt.Sprintf("AS_LTR_%s_%s", asType, letter)] = true
	stager.expandedCategories[fmt.Sprintf("AS_PFX_%s_%s", asType, pfx2)] = true
	stager.isAirspacesExpanded = true

	stager.selectedAirspace = targetTS
	stager.selectedGeoBorder = nil
	stager.focusOnSelected = true
	if stager.probeForm != nil {
		if targetTS != nil {
			stager.probeForm.FillUpFormFromGongstruct(targetTS, "AirspaceTimeSliceType")
		} else {
			stager.probeForm.FillUpFormFromGongstruct(as, "AirspaceType")
		}
	}
	stager.ux_tree()
	stager.ux_maplibre()
}

func (stager *Stager) buildAirspaceEntryNode(
	entry airspaceEntry,
	totalAirspaces int,
	authoritiesByAirspace map[*aixmfeatures.AirspaceType][]*aixmfeatures.AuthorityForAirspaceTimeSliceType,
	airspaceByKey map[string]*aixmfeatures.AirspaceType,
) *tree.Node {
	as := entry.as
	targetTS := entry.targetTS
	label := entry.label

	isHidden := stager.hiddenAirspaces != nil && stager.hiddenAirspaces[as]
	visIcon := string(tree_buttons.BUTTON_visibility)
	visTooltip := "Hide on map"
	fontStyle := tree.NORMAL
	if isHidden {
		visIcon = string(tree_buttons.BUTTON_visibility_off)
		visTooltip = "Show on map"
		fontStyle = tree.ITALIC
	}

	defaultASExpanded := totalAirspaces <= 10 || (targetTS != nil && stager.selectedAirspace == targetTS)
	isASExpanded := stager.isAirspaceNodeExpanded(as, defaultASExpanded)

	asNode := &tree.Node{
		Name:            label,
		FontStyle:       fontStyle,
		IsExpanded:      isASExpanded,
		IsNodeClickable: true,
		OnIsExpandedChange: func(isExpanded bool) {
			stager.mu.Lock()
			defer stager.mu.Unlock()
			if stager.expandedAirspaces == nil {
				stager.expandedAirspaces = make(map[*aixmfeatures.AirspaceType]bool)
			}
			stager.expandedAirspaces[as] = isExpanded
		},
		Buttons: []*tree.Button{
			{
				Name:            "ToggleVisibility_Airspace_" + as.Name,
				Icon:            visIcon,
				HasToolTip:      true,
				ToolTipText:     visTooltip,
				ToolTipPosition: tree.Right,
				OnClick: func() {
					stager.mu.Lock()
					defer stager.mu.Unlock()
					if stager.hiddenAirspaces == nil {
						stager.hiddenAirspaces = make(map[*aixmfeatures.AirspaceType]bool)
					}
					if stager.hiddenAirspaces[as] {
						delete(stager.hiddenAirspaces, as)
					} else {
						stager.hiddenAirspaces[as] = true
						if stager.selectedAirspace == targetTS {
							stager.selectedAirspace = nil
						}
					}
					stager.focusOnSelected = false
					stager.ux_tree()
					stager.ux_maplibre()
				},
			},
		},
		OnClick: func(frontNode *tree.Node) {
			stager.mu.Lock()
			defer stager.mu.Unlock()
			stager.selectAndFocusAirspaceLocked(as)
		},
	}

	// Build navigable child nodes under the zone (Authorities, Classifications, Activations, Geometry & Contributors, Notes)
	asNode.Children = stager.buildAirspaceDetailChildren(
		as,
		targetTS,
		authoritiesByAirspace[as],
		airspaceByKey,
	)
	return asNode
}

func (stager *Stager) appendAirspaceRangeBuckets(
	parentNode *tree.Node,
	keyPrefix string,
	entries []airspaceEntry,
	totalAirspaces int,
	authoritiesByAirspace map[*aixmfeatures.AirspaceType][]*aixmfeatures.AuthorityForAirspaceTimeSliceType,
	airspaceByKey map[string]*aixmfeatures.AirspaceType,
) {
	bucketSize := airspaceGroupBucketSize(len(entries))
	for start := 0; start < len(entries); start += bucketSize {
		end := start + bucketSize
		if end > len(entries) {
			end = len(entries)
		}
		groupEntries := entries[start:end]
		groupIdx := start / bucketSize
		groupKey := fmt.Sprintf("%s_%d", keyPrefix, groupIdx)

		firstShort := groupEntries[0].shortName
		lastShort := groupEntries[len(groupEntries)-1].shortName
		var groupTitle string
		if len(groupEntries) == 1 {
			groupTitle = fmt.Sprintf("[%d] %s (1)", start+1, firstShort)
		} else {
			groupTitle = fmt.Sprintf("[%d–%d] %s -> %s (%d)", start+1, end, firstShort, lastShort, len(groupEntries))
		}

		allGroupHidden := true
		hasSelectedInGroup := false
		for _, ge := range groupEntries {
			if stager.hiddenAirspaces == nil || !stager.hiddenAirspaces[ge.as] {
				allGroupHidden = false
			}
			if ge.targetTS != nil && stager.selectedAirspace == ge.targetTS {
				hasSelectedInGroup = true
			}
		}

		grpVisIcon := string(tree_buttons.BUTTON_visibility)
		grpVisTooltip := fmt.Sprintf("Hide group %s (%d)", groupTitle, len(groupEntries))
		grpFontStyle := tree.NORMAL
		if allGroupHidden {
			grpVisIcon = string(tree_buttons.BUTTON_visibility_off)
			grpVisTooltip = fmt.Sprintf("Show group %s (%d)", groupTitle, len(groupEntries))
			grpFontStyle = tree.ITALIC
		}

		defaultGroupExpanded := totalAirspaces <= 10 || len(entries) <= bucketSize
		isGroupExp := stager.isCategoryExpanded(groupKey, defaultGroupExpanded) || hasSelectedInGroup

		groupNode := &tree.Node{
			Name:       groupTitle,
			FontStyle:  grpFontStyle,
			IsExpanded: isGroupExp,
			OnIsExpandedChange: func(isExpanded bool) {
				stager.mu.Lock()
				defer stager.mu.Unlock()
				if stager.expandedCategories == nil {
					stager.expandedCategories = make(map[string]bool)
				}
				stager.expandedCategories[groupKey] = isExpanded
				stager.ux_tree()
			},
			Buttons: []*tree.Button{
				{
					Name:            "ToggleVisibility_" + groupKey,
					Icon:            grpVisIcon,
					HasToolTip:      true,
					ToolTipText:     grpVisTooltip,
					ToolTipPosition: tree.Right,
					OnClick: func() {
						stager.mu.Lock()
						defer stager.mu.Unlock()
						if stager.hiddenAirspaces == nil {
							stager.hiddenAirspaces = make(map[*aixmfeatures.AirspaceType]bool)
						}
						if allGroupHidden {
							for _, ge := range groupEntries {
								delete(stager.hiddenAirspaces, ge.as)
							}
						} else {
							for _, ge := range groupEntries {
								stager.hiddenAirspaces[ge.as] = true
								if stager.selectedAirspace == ge.targetTS {
									stager.selectedAirspace = nil
								}
							}
						}
						stager.focusOnSelected = false
						stager.ux_tree()
						stager.ux_maplibre()
					},
				},
			},
		}
		parentNode.Children = append(parentNode.Children, groupNode)

		if !isGroupExp {
			groupNode.Children = append(groupNode.Children, &tree.Node{
				Name: fmt.Sprintf("Expand to view %d zones (%s -> %s)...", len(groupEntries), firstShort, lastShort),
			})
			continue
		}

		for _, entry := range groupEntries {
			groupNode.Children = append(groupNode.Children, stager.buildAirspaceEntryNode(
				entry,
				totalAirspaces,
				authoritiesByAirspace,
				airspaceByKey,
			))
		}
	}
}

func (stager *Stager) ux_tree() {
	stager.treeStage.Reset()

	treeInstance := &tree.Tree{
		Name:       "XSD Document & Validation Tree",
		HaveSearch: true,
	}

	if stager.probeForm != nil {
		stager.probeForm.AddCommitNavigationNode(func(gni GongNodeIF) {
			treeInstance.RootNodes = append(treeInstance.RootNodes, gni.(*tree.Node))
		})
	}

	// 1. Semantic Validation Status Node
	statusNode := &tree.Node{
		IsExpanded: true,
	}
	if len(stager.semanticErrors) == 0 {
		statusNode.Name = "XSD Semantic Validation: Valid (0 errors)"
	} else {
		statusNode.Name = fmt.Sprintf("XSD Semantic Validation: %d error(s)", len(stager.semanticErrors))
		for _, errMsg := range stager.semanticErrors {
			statusNode.Children = append(statusNode.Children, &tree.Node{
				Name: errMsg,
			})
		}
	}
	treeInstance.RootNodes = append(treeInstance.RootNodes, statusNode)

	// 2. Document Root Elements Node
	docRootNode := &tree.Node{
		Name:       "XML Document Root Elements",
		IsExpanded: true,
	}
	treeInstance.RootNodes = append(treeInstance.RootNodes, docRootNode)

	for _, inst := range stager.stage.GetInstancesSorted[*AIXMBasicMessage]() {
		inst := inst
		node := &tree.Node{
			Name:            fmt.Sprintf("<AIXMBasicMessage> %s", inst.Name),
			IsExpanded:      true,
			IsNodeClickable: true,
			OnClick: func(frontNode *tree.Node) {
				stager.mu.Lock()
				defer stager.mu.Unlock()
				stager.selectedAirspace = nil
				stager.selectedGeoBorder = nil
				stager.focusOnSelected = false
				if stager.probeForm != nil {
					stager.probeForm.FillUpFormFromGongstruct(inst, "AIXMBasicMessage")
				}
				stager.ux_maplibre()
			},
		}
		docRootNode.Children = append(docRootNode.Children, node)

		if stager.stage.AixmfeaturesStage != nil {
			airspaces := stager.stage.AixmfeaturesStage.GetInstancesSorted[*aixmfeatures.AirspaceType]()
			authorities := stager.stage.AixmfeaturesStage.GetInstancesSorted[*aixmfeatures.AuthorityForAirspaceType]()
			airspaceByKey, authoritiesByAirspace := buildAirspaceAndAuthorityLookups(airspaces, authorities)

			if len(airspaces) > 0 {
				allAirspacesHidden := true
				for _, as := range airspaces {
					if stager.hiddenAirspaces == nil || !stager.hiddenAirspaces[as] {
						allAirspacesHidden = false
						break
					}
				}
				folderVisIcon := string(tree_buttons.BUTTON_visibility)
				folderVisTooltip := "Hide all Airspaces"
				folderFontStyle := tree.NORMAL
				if allAirspacesHidden {
					folderVisIcon = string(tree_buttons.BUTTON_visibility_off)
					folderVisTooltip = "Show all Airspaces"
					folderFontStyle = tree.ITALIC
				}

				asFolder := &tree.Node{
					Name:       fmt.Sprintf("Airspaces (%d)", len(airspaces)),
					FontStyle:  folderFontStyle,
					IsExpanded: stager.isAirspacesExpanded,
					OnIsExpandedChange: func(isExpanded bool) {
						stager.mu.Lock()
						defer stager.mu.Unlock()
						stager.isAirspacesExpanded = isExpanded
					},
					Buttons: []*tree.Button{
						{
							Name:            "ToggleVisibility_AllAirspaces",
							Icon:            folderVisIcon,
							HasToolTip:      true,
							ToolTipText:     folderVisTooltip,
							ToolTipPosition: tree.Right,
							OnClick: func() {
								stager.mu.Lock()
								defer stager.mu.Unlock()
								if stager.hiddenAirspaces == nil {
									stager.hiddenAirspaces = make(map[*aixmfeatures.AirspaceType]bool)
								}
								if allAirspacesHidden {
									for _, item := range airspaces {
										delete(stager.hiddenAirspaces, item)
									}
								} else {
									for _, item := range airspaces {
										stager.hiddenAirspaces[item] = true
									}
									stager.selectedAirspace = nil
								}
								stager.focusOnSelected = false
								stager.ux_tree()
								stager.ux_maplibre()
							},
						},
					},
				}
				node.Children = append(node.Children, asFolder)

				// Group airspaces by category (AIXM Type)
				byCategory := make(map[string][]airspaceEntry)
				var categoryKeys []string

				for _, as := range airspaces {
					as := as
					label := as.Name
					shortName := as.Name
					asType := "OTHER"
					var targetTS *aixmfeatures.AirspaceTimeSliceType

					for _, tsp := range as.TimeSlice {
						if tsp == nil || tsp.AirspaceTimeSlice == nil {
							continue
						}
						ts := tsp.AirspaceTimeSlice
						targetTS = ts
						if ts.Type_XSD != nil && strings.TrimSpace(ts.Type_XSD.EnclosedText) != "" {
							asType = strings.ToUpper(strings.TrimSpace(ts.Type_XSD.EnclosedText))
						}
						desig := ""
						if ts.Designator != nil {
							desig = strings.TrimSpace(ts.Designator.EnclosedText)
						}
						asName := ""
						for _, n := range ts.NameXSD {
							if n != nil && strings.TrimSpace(n.EnclosedText) != "" {
								asName = strings.TrimSpace(n.EnclosedText)
								break
							}
						}
						if desig != "" {
							shortName = desig
						} else if asName != "" {
							shortName = asName
						} else if ts.Id != "" {
							shortName = ts.Id
							if len(shortName) > 22 {
								shortName = shortName[:22] + "…"
							}
						}

						limits := ""
						for _, gcp := range ts.GeometryComponent {
							if gcp != nil && gcp.AirspaceGeometryComponent != nil &&
								gcp.AirspaceGeometryComponent.TheAirspaceVolume != nil &&
								gcp.AirspaceGeometryComponent.TheAirspaceVolume.AirspaceVolume != nil {
								vol := gcp.AirspaceGeometryComponent.TheAirspaceVolume.AirspaceVolume
								if limits == "" {
									limits = formatVerticalLimits(vol.LowerLimit, vol.UpperLimit)
								}
							}
						}

						parts := []string{}
						if asType != "" {
							parts = append(parts, "["+asType+"]")
						}
						if desig != "" {
							parts = append(parts, desig)
						}
						if asName != "" && asName != desig {
							parts = append(parts, "- "+asName)
						}
						if limits != "" {
							parts = append(parts, "("+limits+")")
						}
						if len(parts) > 0 {
							label = strings.Join(parts, " ")
						}
						break
					}

					if _, exists := byCategory[asType]; !exists {
						categoryKeys = append(categoryKeys, asType)
					}
					byCategory[asType] = append(byCategory[asType], airspaceEntry{
						as:        as,
						targetTS:  targetTS,
						asType:    asType,
						shortName: shortName,
						label:     label,
					})
				}

				slices.SortFunc(categoryKeys, func(a, b string) int {
					ordA, titleA := airspaceCategoryInfo(a)
					ordB, titleB := airspaceCategoryInfo(b)
					if ordA != ordB {
						return ordA - ordB
					}
					return strings.Compare(titleA, titleB)
				})

				for _, catType := range categoryKeys {
					catType := catType
					entries := byCategory[catType]
					slices.SortFunc(entries, func(a, b airspaceEntry) int {
						la := airspaceFirstLetter(a.shortName)
						lb := airspaceFirstLetter(b.shortName)
						if cmp := compareGroupKeyStrings(la, lb); cmp != 0 {
							return cmp
						}
						if cmp := naturalCompareStrings(a.shortName, b.shortName); cmp != 0 {
							return cmp
						}
						return naturalCompareStrings(a.label, b.label)
					})
					_, catTitle := airspaceCategoryInfo(catType)
					catKey := "AS_CAT_" + catType

					allCatHidden := true
					hasSelectedInCat := false
					for _, e := range entries {
						if stager.hiddenAirspaces == nil || !stager.hiddenAirspaces[e.as] {
							allCatHidden = false
						}
						if e.targetTS != nil && stager.selectedAirspace == e.targetTS {
							hasSelectedInCat = true
						}
					}

					catVisIcon := string(tree_buttons.BUTTON_visibility)
					catVisTooltip := fmt.Sprintf("Hide category %s (%d)", catType, len(entries))
					catFontStyle := tree.NORMAL
					if allCatHidden {
						catVisIcon = string(tree_buttons.BUTTON_visibility_off)
						catVisTooltip = fmt.Sprintf("Show category %s (%d)", catType, len(entries))
						catFontStyle = tree.ITALIC
					}

					defaultCatExpanded := len(airspaces) <= 30
					isCatExp := stager.isCategoryExpanded(catKey, defaultCatExpanded) || hasSelectedInCat

					catNode := &tree.Node{
						Name:       fmt.Sprintf("%s (%d)", catTitle, len(entries)),
						FontStyle:  catFontStyle,
						IsExpanded: isCatExp,
						OnIsExpandedChange: func(isExpanded bool) {
							stager.mu.Lock()
							defer stager.mu.Unlock()
							if stager.expandedCategories == nil {
								stager.expandedCategories = make(map[string]bool)
							}
							stager.expandedCategories[catKey] = isExpanded
						},
						Buttons: []*tree.Button{
							{
								Name:            "ToggleVisibility_Category_" + catType,
								Icon:            catVisIcon,
								HasToolTip:      true,
								ToolTipText:     catVisTooltip,
								ToolTipPosition: tree.Right,
								OnClick: func() {
									stager.mu.Lock()
									defer stager.mu.Unlock()
									if stager.hiddenAirspaces == nil {
										stager.hiddenAirspaces = make(map[*aixmfeatures.AirspaceType]bool)
									}
									if allCatHidden {
										for _, e := range entries {
											delete(stager.hiddenAirspaces, e.as)
										}
									} else {
										for _, e := range entries {
											stager.hiddenAirspaces[e.as] = true
											if stager.selectedAirspace == e.targetTS {
												stager.selectedAirspace = nil
											}
										}
									}
									stager.focusOnSelected = false
									stager.ux_tree()
									stager.ux_maplibre()
								},
							},
						},
					}
					asFolder.Children = append(asFolder.Children, catNode)

					// Intermediate level between Zone Category and Zones:
					// Group sorted entries by area first letter (e.g. [E], [L], [B], [G], ...),
					// and if a single first-letter group has > 80 zones across multiple 2-letter
					// ICAO prefixes (e.g. EB, ED, EE, EF, EG, LF, LE, LI), sub-group by 2-letter prefix.
					byLetter := make(map[string][]airspaceEntry)
					var letterKeys []string
					for _, e := range entries {
						ltr := airspaceFirstLetter(e.shortName)
						if _, exists := byLetter[ltr]; !exists {
							letterKeys = append(letterKeys, ltr)
						}
						byLetter[ltr] = append(byLetter[ltr], e)
					}
					slices.SortFunc(letterKeys, compareGroupKeyStrings)

					for _, letter := range letterKeys {
						letter := letter
						letterEntries := byLetter[letter]
						letterKey := fmt.Sprintf("AS_LTR_%s_%s", catType, letter)

						firstShort := letterEntries[0].shortName
						lastShort := letterEntries[len(letterEntries)-1].shortName
						var letterTitle string
						if len(letterEntries) == 1 {
							letterTitle = fmt.Sprintf("[%s] %s (1)", letter, firstShort)
						} else {
							letterTitle = fmt.Sprintf("[%s] %s -> %s (%d)", letter, firstShort, lastShort, len(letterEntries))
						}

						allLetterHidden := true
						hasSelectedInLetter := false
						for _, le := range letterEntries {
							if stager.hiddenAirspaces == nil || !stager.hiddenAirspaces[le.as] {
								allLetterHidden = false
							}
							if le.targetTS != nil && stager.selectedAirspace == le.targetTS {
								hasSelectedInLetter = true
							}
						}

						ltrVisIcon := string(tree_buttons.BUTTON_visibility)
						ltrVisTooltip := fmt.Sprintf("Hide area [%s] in %s (%d)", letter, catType, len(letterEntries))
						ltrFontStyle := tree.NORMAL
						if allLetterHidden {
							ltrVisIcon = string(tree_buttons.BUTTON_visibility_off)
							ltrVisTooltip = fmt.Sprintf("Show area [%s] in %s (%d)", letter, catType, len(letterEntries))
							ltrFontStyle = tree.ITALIC
						}

						defaultLetterExpanded := len(airspaces) <= 10 || (len(letterEntries) <= 25 && len(airspaces) <= 80)
						isLetterExp := stager.isCategoryExpanded(letterKey, defaultLetterExpanded) || hasSelectedInLetter

						letterNode := &tree.Node{
							Name:       letterTitle,
							FontStyle:  ltrFontStyle,
							IsExpanded: isLetterExp,
							OnIsExpandedChange: func(isExpanded bool) {
								stager.mu.Lock()
								defer stager.mu.Unlock()
								if stager.expandedCategories == nil {
									stager.expandedCategories = make(map[string]bool)
								}
								stager.expandedCategories[letterKey] = isExpanded
								stager.ux_tree()
							},
							Buttons: []*tree.Button{
								{
									Name:            "ToggleVisibility_" + letterKey,
									Icon:            ltrVisIcon,
									HasToolTip:      true,
									ToolTipText:     ltrVisTooltip,
									ToolTipPosition: tree.Right,
									OnClick: func() {
										stager.mu.Lock()
										defer stager.mu.Unlock()
										if stager.hiddenAirspaces == nil {
											stager.hiddenAirspaces = make(map[*aixmfeatures.AirspaceType]bool)
										}
										if allLetterHidden {
											for _, le := range letterEntries {
												delete(stager.hiddenAirspaces, le.as)
											}
										} else {
											for _, le := range letterEntries {
												stager.hiddenAirspaces[le.as] = true
												if stager.selectedAirspace == le.targetTS {
													stager.selectedAirspace = nil
												}
											}
										}
										stager.focusOnSelected = false
										stager.ux_tree()
										stager.ux_maplibre()
									},
								},
							},
						}
						catNode.Children = append(catNode.Children, letterNode)

						// Check whether this first-letter group is large (> 80 items) and spans multiple 2-letter area prefixes
						byPfx2 := make(map[string][]airspaceEntry)
						var pfx2Keys []string
						if len(letterEntries) > 80 {
							for _, le := range letterEntries {
								p2 := airspaceTwoLetterPrefix(le.shortName)
								if _, exists := byPfx2[p2]; !exists {
									pfx2Keys = append(pfx2Keys, p2)
								}
								byPfx2[p2] = append(byPfx2[p2], le)
							}
							slices.SortFunc(pfx2Keys, compareGroupKeyStrings)
						}

						if len(pfx2Keys) > 1 {
							for _, pfx2 := range pfx2Keys {
								pfx2 := pfx2
								subEntries := byPfx2[pfx2]
								subKey := fmt.Sprintf("AS_PFX_%s_%s", catType, pfx2)

								subFirst := subEntries[0].shortName
								subLast := subEntries[len(subEntries)-1].shortName
								var subTitle string
								if len(subEntries) == 1 {
									subTitle = fmt.Sprintf("[%s] %s (1)", pfx2, subFirst)
								} else {
									subTitle = fmt.Sprintf("[%s] %s -> %s (%d)", pfx2, subFirst, subLast, len(subEntries))
								}

								allSubHidden := true
								hasSelectedInSub := false
								for _, se := range subEntries {
									if stager.hiddenAirspaces == nil || !stager.hiddenAirspaces[se.as] {
										allSubHidden = false
									}
									if se.targetTS != nil && stager.selectedAirspace == se.targetTS {
										hasSelectedInSub = true
									}
								}

								subVisIcon := string(tree_buttons.BUTTON_visibility)
								subVisTooltip := fmt.Sprintf("Hide area [%s] in %s (%d)", pfx2, catType, len(subEntries))
								subFontStyle := tree.NORMAL
								if allSubHidden {
									subVisIcon = string(tree_buttons.BUTTON_visibility_off)
									subVisTooltip = fmt.Sprintf("Show area [%s] in %s (%d)", pfx2, catType, len(subEntries))
									subFontStyle = tree.ITALIC
								}

								isSubExp := stager.isCategoryExpanded(subKey, false) || hasSelectedInSub

								subNode := &tree.Node{
									Name:       subTitle,
									FontStyle:  subFontStyle,
									IsExpanded: isSubExp,
									OnIsExpandedChange: func(isExpanded bool) {
										stager.mu.Lock()
										defer stager.mu.Unlock()
										if stager.expandedCategories == nil {
											stager.expandedCategories = make(map[string]bool)
										}
										stager.expandedCategories[subKey] = isExpanded
										stager.ux_tree()
									},
									Buttons: []*tree.Button{
										{
											Name:            "ToggleVisibility_" + subKey,
											Icon:            subVisIcon,
											HasToolTip:      true,
											ToolTipText:     subVisTooltip,
											ToolTipPosition: tree.Right,
											OnClick: func() {
												stager.mu.Lock()
												defer stager.mu.Unlock()
												if stager.hiddenAirspaces == nil {
													stager.hiddenAirspaces = make(map[*aixmfeatures.AirspaceType]bool)
												}
												if allSubHidden {
													for _, se := range subEntries {
														delete(stager.hiddenAirspaces, se.as)
													}
												} else {
													for _, se := range subEntries {
														stager.hiddenAirspaces[se.as] = true
														if stager.selectedAirspace == se.targetTS {
															stager.selectedAirspace = nil
														}
													}
												}
												stager.focusOnSelected = false
												stager.ux_tree()
												stager.ux_maplibre()
											},
										},
									},
								}
								letterNode.Children = append(letterNode.Children, subNode)

								if !isSubExp {
									subNode.Children = append(subNode.Children, &tree.Node{
										Name: fmt.Sprintf("Expand to view %d zones (%s -> %s)...", len(subEntries), subFirst, subLast),
									})
									continue
								}

								for _, entry := range subEntries {
									subNode.Children = append(subNode.Children, stager.buildAirspaceEntryNode(
										entry,
										len(airspaces),
										authoritiesByAirspace,
										airspaceByKey,
									))
								}
							}
							continue
						}

						if !isLetterExp && len(airspaces) > 200 {
							letterNode.Children = append(letterNode.Children, &tree.Node{
								Name: fmt.Sprintf("Expand to view %d zones (%s -> %s)...", len(letterEntries), firstShort, lastShort),
							})
							continue
						}

						for _, entry := range letterEntries {
							letterNode.Children = append(letterNode.Children, stager.buildAirspaceEntryNode(
								entry,
								len(airspaces),
								authoritiesByAirspace,
								airspaceByKey,
							))
						}
					}
				}
			}

			// Top-level Authorities for Airspace folder (allows browsing by Authority & jumping to Assigned Airspace)
			if len(authorities) > 0 {
				authFolder := &tree.Node{
					Name:       fmt.Sprintf("Authorities for Airspace (%d)", len(authorities)),
					IsExpanded: stager.isAuthoritiesExpanded || len(authorities) <= 10,
					OnIsExpandedChange: func(isExpanded bool) {
						stager.mu.Lock()
						defer stager.mu.Unlock()
						stager.isAuthoritiesExpanded = isExpanded
						if len(authorities) > 40 {
							stager.ux_tree()
						}
					},
				}
				node.Children = append(node.Children, authFolder)

				if authFolder.IsExpanded || len(authorities) <= 40 {
					for _, auth := range authorities {
						auth := auth
						for _, tsp := range auth.TimeSlice {
							if tsp == nil || tsp.AuthorityForAirspaceTimeSlice == nil {
								continue
							}
							authTS := tsp.AuthorityForAirspaceTimeSlice
							summary := formatAuthoritySummary(authTS)
							assignedLabel := ""
							var assignedAS *aixmfeatures.AirspaceType
							if authTS.AssignedAirspace != nil {
								assignedLabel = formatXlinkPropertyLabel(authTS.AssignedAirspace.Title, authTS.AssignedAirspace.Href)
								if authTS.AssignedAirspace.Href != "" {
									assignedAS = airspaceByKey[normalizeAirspaceKey(authTS.AssignedAirspace.Href)]
								}
							}
							itemTitle := summary
							if assignedLabel != "" {
								itemTitle = fmt.Sprintf("%s -> %s", summary, assignedLabel)
							}
							authItemNode := &tree.Node{
								Name:            itemTitle,
								IsNodeClickable: true,
								OnClick: func(frontNode *tree.Node) {
									stager.mu.Lock()
									defer stager.mu.Unlock()
									if stager.probeForm != nil {
										stager.probeForm.FillUpFormFromGongstruct(authTS, "AuthorityForAirspaceTimeSliceType")
									}
								},
							}
							if authTS.ResponsibleOrganisation != nil {
								orgProp := authTS.ResponsibleOrganisation
								authItemNode.Children = append(authItemNode.Children, &tree.Node{
									Name:            "Responsible Organisation: " + formatXlinkPropertyLabel(orgProp.Title, orgProp.Href),
									IsNodeClickable: true,
									OnClick: func(frontNode *tree.Node) {
										stager.mu.Lock()
										defer stager.mu.Unlock()
										if stager.probeForm != nil {
											stager.probeForm.FillUpFormFromGongstruct(orgProp, "OrganisationAuthorityPropertyType")
										}
									},
								})
							}
							if assignedLabel != "" {
								authItemNode.Children = append(authItemNode.Children, &tree.Node{
									Name:            "-> Assigned Airspace: " + assignedLabel,
									IsNodeClickable: true,
									OnClick: func(frontNode *tree.Node) {
										stager.mu.Lock()
										defer stager.mu.Unlock()
										if assignedAS != nil {
											stager.selectAndFocusAirspaceLocked(assignedAS)
										} else if stager.probeForm != nil && authTS.AssignedAirspace != nil {
											stager.probeForm.FillUpFormFromGongstruct(authTS.AssignedAirspace, "AirspacePropertyType")
										}
									},
								})
							}
							authItemNode.Children = append(authItemNode.Children, stager.buildNoteNodes(authTS.Annotation)...)
							authFolder.Children = append(authFolder.Children, authItemNode)
							break
						}
					}
				} else {
					authFolder.Children = append(authFolder.Children, &tree.Node{
						Name: fmt.Sprintf("Expand to view %d AuthorityForAirspace entries...", len(authorities)),
					})
				}
			}

			borders := stager.stage.AixmfeaturesStage.GetInstancesSorted[*aixmfeatures.GeoBorderType]()
			if len(borders) > 0 {
				allBordersHidden := true
				for _, gb := range borders {
					if stager.hiddenGeoBorders == nil || !stager.hiddenGeoBorders[gb] {
						allBordersHidden = false
						break
					}
				}
				gbFolderVisIcon := string(tree_buttons.BUTTON_visibility)
				gbFolderVisTooltip := "Hide all GeoBorders"
				gbFolderFontStyle := tree.NORMAL
				if allBordersHidden {
					gbFolderVisIcon = string(tree_buttons.BUTTON_visibility_off)
					gbFolderVisTooltip = "Show all GeoBorders"
					gbFolderFontStyle = tree.ITALIC
				}

				gbFolder := &tree.Node{
					Name:       fmt.Sprintf("GeoBorders (%d)", len(borders)),
					FontStyle:  gbFolderFontStyle,
					IsExpanded: stager.isGeoBordersExpanded,
					OnIsExpandedChange: func(isExpanded bool) {
						stager.mu.Lock()
						defer stager.mu.Unlock()
						stager.isGeoBordersExpanded = isExpanded
					},
					Buttons: []*tree.Button{
						{
							Name:            "ToggleVisibility_AllGeoBorders",
							Icon:            gbFolderVisIcon,
							HasToolTip:      true,
							ToolTipText:     gbFolderVisTooltip,
							ToolTipPosition: tree.Right,
							OnClick: func() {
								stager.mu.Lock()
								defer stager.mu.Unlock()
								if stager.hiddenGeoBorders == nil {
									stager.hiddenGeoBorders = make(map[*aixmfeatures.GeoBorderType]bool)
								}
								if allBordersHidden {
									for _, item := range borders {
										delete(stager.hiddenGeoBorders, item)
									}
								} else {
									for _, item := range borders {
										stager.hiddenGeoBorders[item] = true
									}
									stager.selectedGeoBorder = nil
								}
								stager.focusOnSelected = false
								stager.ux_tree()
								stager.ux_maplibre()
							},
						},
					},
				}
				node.Children = append(node.Children, gbFolder)

				// Group GeoBorders by category (Type)
				byGBCategory := make(map[string][]geoBorderEntry)
				var gbCatKeys []string

				for _, gb := range borders {
					gb := gb
					label := gb.Name
					gbType := "BORDER"
					var targetTS *aixmfeatures.GeoBorderTimeSliceType

					for _, tsp := range gb.TimeSlice {
						if tsp == nil || tsp.GeoBorderTimeSlice == nil {
							continue
						}
						ts := tsp.GeoBorderTimeSlice
						targetTS = ts
						if ts.Type_XSD != nil && strings.TrimSpace(ts.Type_XSD.EnclosedText) != "" {
							gbType = strings.ToUpper(strings.TrimSpace(ts.Type_XSD.EnclosedText))
						}
						gbName := ""
						for _, n := range ts.NameXSD {
							if n != nil && strings.TrimSpace(n.EnclosedText) != "" {
								gbName = strings.TrimSpace(n.EnclosedText)
								break
							}
						}
						if gbName != "" {
							label = fmt.Sprintf("[%s] %s", gbType, gbName)
						}
						break
					}

					if _, exists := byGBCategory[gbType]; !exists {
						gbCatKeys = append(gbCatKeys, gbType)
					}
					byGBCategory[gbType] = append(byGBCategory[gbType], geoBorderEntry{
						gb:       gb,
						targetTS: targetTS,
						gbType:   gbType,
						label:    label,
					})
				}

				slices.SortFunc(gbCatKeys, func(a, b string) int {
					ordA, titleA := geoBorderCategoryInfo(a)
					ordB, titleB := geoBorderCategoryInfo(b)
					if ordA != ordB {
						return ordA - ordB
					}
					return strings.Compare(titleA, titleB)
				})

				for _, gbCatType := range gbCatKeys {
					gbCatType := gbCatType
					entries := byGBCategory[gbCatType]
					_, catTitle := geoBorderCategoryInfo(gbCatType)
					catKey := "GB_CAT_" + gbCatType

					allCatHidden := true
					for _, e := range entries {
						if stager.hiddenGeoBorders == nil || !stager.hiddenGeoBorders[e.gb] {
							allCatHidden = false
							break
						}
					}

					catVisIcon := string(tree_buttons.BUTTON_visibility)
					catVisTooltip := fmt.Sprintf("Hide category %s (%d)", gbCatType, len(entries))
					catFontStyle := tree.NORMAL
					if allCatHidden {
						catVisIcon = string(tree_buttons.BUTTON_visibility_off)
						catVisTooltip = fmt.Sprintf("Show category %s (%d)", gbCatType, len(entries))
						catFontStyle = tree.ITALIC
					}

					defaultGBCatExpanded := len(borders) <= 30
					isGBCatExp := stager.isCategoryExpanded(catKey, defaultGBCatExpanded)

					catNode := &tree.Node{
						Name:       fmt.Sprintf("%s (%d)", catTitle, len(entries)),
						FontStyle:  catFontStyle,
						IsExpanded: isGBCatExp,
						OnIsExpandedChange: func(isExpanded bool) {
							stager.mu.Lock()
							defer stager.mu.Unlock()
							if stager.expandedCategories == nil {
								stager.expandedCategories = make(map[string]bool)
							}
							stager.expandedCategories[catKey] = isExpanded
						},
						Buttons: []*tree.Button{
							{
								Name:            "ToggleVisibility_GBCategory_" + gbCatType,
								Icon:            catVisIcon,
								HasToolTip:      true,
								ToolTipText:     catVisTooltip,
								ToolTipPosition: tree.Right,
								OnClick: func() {
									stager.mu.Lock()
									defer stager.mu.Unlock()
									if stager.hiddenGeoBorders == nil {
										stager.hiddenGeoBorders = make(map[*aixmfeatures.GeoBorderType]bool)
									}
									if allCatHidden {
										for _, e := range entries {
											delete(stager.hiddenGeoBorders, e.gb)
										}
									} else {
										for _, e := range entries {
											stager.hiddenGeoBorders[e.gb] = true
											if stager.selectedGeoBorder == e.targetTS {
												stager.selectedGeoBorder = nil
											}
										}
									}
									stager.focusOnSelected = false
									stager.ux_tree()
									stager.ux_maplibre()
								},
							},
						},
					}
					gbFolder.Children = append(gbFolder.Children, catNode)

					for _, entry := range entries {
						gb := entry.gb
						targetTS := entry.targetTS
						label := entry.label

						isHidden := stager.hiddenGeoBorders != nil && stager.hiddenGeoBorders[gb]
						visIcon := string(tree_buttons.BUTTON_visibility)
						visTooltip := "Hide on map"
						fontStyle := tree.NORMAL
						if isHidden {
							visIcon = string(tree_buttons.BUTTON_visibility_off)
							visTooltip = "Show on map"
							fontStyle = tree.ITALIC
						}

						gbNode := &tree.Node{
							Name:            label,
							FontStyle:       fontStyle,
							IsNodeClickable: true,
							Buttons: []*tree.Button{
								{
									Name:            "ToggleVisibility_GeoBorder_" + gb.Name,
									Icon:            visIcon,
									HasToolTip:      true,
									ToolTipText:     visTooltip,
									ToolTipPosition: tree.Right,
									OnClick: func() {
										stager.mu.Lock()
										defer stager.mu.Unlock()
										if stager.hiddenGeoBorders == nil {
											stager.hiddenGeoBorders = make(map[*aixmfeatures.GeoBorderType]bool)
										}
										if stager.hiddenGeoBorders[gb] {
											delete(stager.hiddenGeoBorders, gb)
										} else {
											stager.hiddenGeoBorders[gb] = true
											if stager.selectedGeoBorder == targetTS {
												stager.selectedGeoBorder = nil
											}
										}
										stager.focusOnSelected = false
										stager.ux_tree()
										stager.ux_maplibre()
									},
								},
							},
							OnClick: func(frontNode *tree.Node) {
								stager.mu.Lock()
								defer stager.mu.Unlock()
								if stager.hiddenGeoBorders != nil && stager.hiddenGeoBorders[gb] {
									delete(stager.hiddenGeoBorders, gb)
								}
								stager.selectedGeoBorder = targetTS
								stager.selectedAirspace = nil
								stager.focusOnSelected = true
								if stager.probeForm != nil {
									if targetTS != nil {
										stager.probeForm.FillUpFormFromGongstruct(targetTS, "GeoBorderTimeSliceType")
									} else {
										stager.probeForm.FillUpFormFromGongstruct(gb, "GeoBorderType")
									}
								}
								stager.ux_tree()
								stager.ux_maplibre()
							},
						}
						if targetTS != nil {
							if targetTS.Border != nil && targetTS.Border.Curve != nil {
								crv := targetTS.Border.Curve
								gbNode.Children = append(gbNode.Children, &tree.Node{
									Name:            "Border Curve: " + crv.Id,
									IsNodeClickable: true,
									OnClick: func(frontNode *tree.Node) {
										stager.mu.Lock()
										defer stager.mu.Unlock()
										if stager.probeForm != nil {
											stager.probeForm.FillUpFormFromGongstruct(crv, "CurveType")
										}
									},
								})
							}
							gbNode.Children = append(gbNode.Children, stager.buildNoteNodes(targetTS.Annotation)...)
						}
						catNode.Children = append(catNode.Children, gbNode)
					}
				}
			}
		}
	}

	// 3. Multi-Package Stages Overview
	stagesNode := &tree.Node{
		Name:       "Multi-Package Stages",
		IsExpanded: false,
	}
	treeInstance.RootNodes = append(treeInstance.RootNodes, stagesNode)

	if stager.stage.XlinkStage != nil {
		pkgNode := &tree.Node{
			Name:       "Sub-Package: xlink (XlinkStage)",
			IsExpanded: false,
		}
		stagesNode.Children = append(stagesNode.Children, pkgNode)
	}

	if stager.stage.GmlStage != nil {
		pkgNode := &tree.Node{
			Name:       "Sub-Package: gml (GmlStage)",
			IsExpanded: false,
		}
		stagesNode.Children = append(stagesNode.Children, pkgNode)
	}

	if stager.stage.AixmabstractgmlobjecttypesStage != nil {
		pkgNode := &tree.Node{
			Name:       "Sub-Package: aixmabstractgmlobjecttypes (AixmabstractgmlobjecttypesStage)",
			IsExpanded: false,
		}
		stagesNode.Children = append(stagesNode.Children, pkgNode)
	}

	if stager.stage.AixmdatatypesStage != nil {
		pkgNode := &tree.Node{
			Name:       "Sub-Package: aixmdatatypes (AixmdatatypesStage)",
			IsExpanded: false,
		}
		stagesNode.Children = append(stagesNode.Children, pkgNode)
	}

	if stager.stage.AixmfeaturesStage != nil {
		pkgNode := &tree.Node{
			Name:       "Sub-Package: aixmfeatures (AixmfeaturesStage)",
			IsExpanded: false,
		}
		stagesNode.Children = append(stagesNode.Children, pkgNode)
	}

	{
		pkgNode := &tree.Node{
			Name:       "Package: models (root)",
			IsExpanded: false,
		}
		stagesNode.Children = append(stagesNode.Children, pkgNode)
	}

	stager.treeStage.StageBranch(treeInstance)
	stager.treeStage.Commit()
}
